{"action":"write","path":"relative/sections/01-header.html","content":"<style>
#top {
  background: #fff8f0;
  color: #1e3d2f;
  padding: 1.25rem 1.5rem;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}
#top .brand {
  display: block;
  font-size: 1.75rem;
  font-weight: 700;
  color: #1e3d2f;
  text-decoration: none;
  margin-bottom: 0.5rem;
}
#top nav {
  margin-top: 0.25rem;
}
#top nav ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}
#top nav li { list-style: none; }
#top nav a {
  color: #1e3d2f;
  text-decoration: none;
  font-weight: 600;
  padding: 0.35rem 0.5rem;
  border-radius: 0.375rem;
  border: 2px solid transparent;
}
#top nav a:hover, #top nav a:focus {
  border-color: #b4533d;
  background: #f5e9d8;
}
@media (max-width: 600px) {
  #top { padding: 1rem; }
  #top .brand { font-size: 1.5rem; }
  #top nav ul { justify-content: flex-start; }
}
</style>
<header id="top">
  <a href="#top" class="brand">Common Ground Coffee</a>
  <nav aria-label="Primary">
    <ul>
      <li><a href="#menu">Menu</a></li>
      <li><a href="#mission">Mission</a></li>
      <li><a href="#events">Events</a></li>
      <li><a href="#visit">Visit</a></li>
    </ul>
  </nav>
</header>"}
